import re

FIELD = re.compile(r'^(?P<name>\S+)\s{2,}(?:\((?P<domain>[^)]+)\)\s+)?(?P<type>\S.*?)(?:\s+CHARACTER SET (?P<charset>\S+))?\s+(?P<null>Not Null|Nullable)(?:\s+DEFAULT\s+(?P<default>.*?))?\s*$')
COMP = re.compile(r'^(?P<name>\S+)\s{2,}(?:\((?P<domain>[^)]+)\)\s+)?(?:(?P<type>\S.*?)\s+)?Computed by:\s*(?P<expr>.*?)\s*$')
CONS = re.compile(r'^CONSTRAINT\s+(?P<name>\S+?):\s*$')
KEY = re.compile(r'^(?P<type>Foreign key|Primary key|Unique key)\s*\((?P<cols>[^)]*)\)\s*(?P<rest>.*?)\s*$')
TRG = re.compile(r'^(?P<name>[^,\s]+),\s*Sequence:\s*(?P<seq>\d+),\s*Type:\s*(?P<type>[^,]+?),\s*(?P<status>\S+)\s*$')

def newfield(name, domain, typ, charset, null, default, comp):
    return {'Field': name, 'Domain': domain or '', 'Type': typ or '', 'Character set': charset or '', 'Nullability': null or '', 'Default': default or '', 'Computed by': comp or '', 'Collation': '', 'Check': '', 'Extra': ''}

def parse(lines):
    fields, flines = [], []
    cons, clines = [], []
    trgs, tlines = [], []
    skip = []
    mode = 'fields'
    cur = None
    for i, raw in enumerate(lines):
        s = raw.strip()
        if not s:
            continue
        if s.startswith('SQL>') or re.match(r'^Triggers on Table\s+\S+:', s):
            skip.append(i)
            if s.startswith('Triggers'):
                mode = 'triggers'
            continue
        m = CONS.match(s)
        if m:
            mode = 'cons'
            cur = {'Constraint': m.group('name'), 'Type': '', 'Columns': '', 'Definition': ''}
            cons.append(cur)
            clines.append(i)
            continue
        if mode == 'triggers':
            m = TRG.match(s)
            if m:
                trgs.append({'Trigger': m.group('name'), 'Sequence': int(m.group('seq')), 'Type': m.group('type'), 'Status': m.group('status')})
                tlines.append(i)
            continue
        if mode == 'cons' and cur is not None and raw[:1].isspace():
            k = KEY.match(s)
            if k:
                cur['Type'] = k.group('type')
                cur['Columns'] = k.group('cols')
                cur['Definition'] = k.group('rest')
            elif s.upper().startswith('CHECK'):
                cur['Type'] = 'CHECK'
                cur['Definition'] = s
            else:
                cur['Definition'] = (cur['Definition'] + ' ' + s).strip()
            clines.append(i)
            continue
        if mode == 'fields':
            if raw[:1].isspace() and fields:
                f = fields[-1]
                if s.upper().startswith('COLLATE'):
                    f['Collation'] = s.split(None, 1)[1] if len(s.split()) > 1 else ''
                elif s.upper().startswith('CHECK'):
                    f['Check'] = s
                else:
                    f['Extra'] = (f['Extra'] + ' ' + s).strip()
                flines.append(i)
                continue
            m = COMP.match(raw.rstrip())
            if m:
                fields.append(newfield(m.group('name'), m.group('domain'), m.group('type'), '', '', '', m.group('expr')))
                flines.append(i)
                continue
            m = FIELD.match(raw.rstrip())
            if m:
                fields.append(newfield(m.group('name'), m.group('domain'), m.group('type'), m.group('charset'), m.group('null'), m.group('default'), ''))
                flines.append(i)
    blocks = []
    if fields:
        blocks.append({'name': 'fields', 'kind': 'table', 'lines': flines, 'records': fields})
    if cons:
        blocks.append({'name': 'constraints', 'kind': 'table', 'lines': clines, 'records': cons})
    if trgs:
        blocks.append({'name': 'triggers', 'kind': 'table', 'lines': tlines, 'records': trgs})
    return {'blocks': blocks, 'skip': skip}
